17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Objects;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
108	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
109	            return new ResponseEntity<>(HttpStatus.CONFLICT);
110	        }
111	        if (owner.getRegistrationDate() == null) {
112	            owner.setRegistrationDate(LocalDate.now());
113	        }
114	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
115	        owner.setCity(normalizeCity(owner.getCity()));
116	        owner.setCustomerCode(generateCustomerCode(owner.getCity()));
117	        this.clinicService.saveOwner(owner);
118	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
119	        headers.setLocation(UriComponentsBuilder.newInstance()
120	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
121	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
122	    }
123	
124	    /**
125	     * Generates the customer code for a newly created owner. The code is formatted as
126	     * '&lt;UPPERCASE_CITY&gt;-&lt;NNNN&gt;' where NNNN is one more than the number of owners that
127	     * already exist in that city, zero-padded to four digits (for example 'LONDON-0007').
128	     * Cities are matched ignoring letter case.
129	     */
130	    private String generateCustomerCode(String city) {
131	        long ownersInCity = this.clinicService.findAllOwners().stream()
132	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
133	            .count();
134	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
135	    }
136	
137	    /**
138	     * Normalizes the city of a newly created owner. If an owner already exists in the same
139	     * city (matched ignoring letter case), that existing owner's exact spelling of the city is
140	     * reused so that all owners in a city share one canonical spelling. Otherwise the supplied
141	     * city is title-cased, capitalizing the first letter of each whitespace-separated word and
142	     * lowercasing the rest, so for example "new york" becomes "New York".
143	     */
144	    private String normalizeCity(String city) {
145	        if (city == null) {
146	            return null;
147	        }
148	        return this.clinicService.findAllOwners().stream()
149	            .map(Owner::getCity)
150	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
151	            .findFirst()
152	            .orElseGet(() -> toTitleCase(city));
153	    }
154	
155	    /**
156	     * Title-cases the given value by capitalizing the first letter of each whitespace-separated
157	     * word and lowercasing the remaining letters, preserving the original whitespace: for example
158	     * "new  YORK" becomes "New  York".
159	     */
160	    private static String toTitleCase(String value) {
161	        StringBuilder result = new StringBuilder(value.length());
162	        boolean capitalizeNext = true;
163	        for (int i = 0; i < value.length(); i++) {
164	            char c = value.charAt(i);
165	            if (Character.isWhitespace(c)) {
166	                capitalizeNext = true;
167	                result.append(c);
168	            } else if (capitalizeNext) {
169	                result.append(Character.toTitleCase(c));
170	                capitalizeNext = false;
171	            } else {
172	                result.append(Character.toLowerCase(c));
173	            }
174	        }
175	        return result.toString();
176	    }
177	
178	    /**
179	     * Determines whether an owner already exists that uses the same telephone number
180	     * as the given one. Telephone numbers must be unique across all owners. The
181	     * comparison ignores letter case and any surrounding or repeated whitespace.
182	     */
183	    private boolean isDuplicateOwner(Owner owner) {
184	        String telephone = normalizeTelephone(owner.getTelephone());
185	        return this.clinicService.findAllOwners().stream()
186	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
187	    }
188	
189	    /**
190	     * Normalizes a telephone number for storage and comparison by stripping spaces, dashes
191	     * and parentheses so that only digits remain: for example "(613) 555-0100" becomes
192	     * "6135550100". This lets differently punctuated forms of the same number be treated as
193	     * equal for the uniqueness check and stored in a single canonical form.
194	     */
195	    private static String normalizeTelephone(String telephone) {
196	        if (telephone == null) {
197	            return null;
198	        }
199	        return telephone.replaceAll("[\\s()-]", "");
200	    }
201	
202	    /**
203	     * Determines whether another owner already uses the same email address as the given one.
204	     * Email addresses, when supplied, must be unique across all owners. An owner without an
205	     * email address is never considered a duplicate. The comparison ignores letter case and
206	     * any surrounding or repeated whitespace.
207	     */
208	    private boolean isDuplicateEmail(Owner owner) {
209	        String email = normalize(owner.getEmail());
210	        if (email == null || email.isEmpty()) {
211	            return false;
212	        }
213	        return this.clinicService.findAllOwners().stream()
214	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
215	    }
216	
217	    /**
218	     * Normalizes a user-supplied value for duplicate detection so that comparisons ignore
219	     * letter case and any surrounding or repeated whitespace: for example "  john   smith "
220	     * and "John Smith" normalize to the same key and so count as the same person.
221	     */
222	    private static String normalize(String value) {
223	        if (value == null) {
224	            return null;
225	        }
226	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
227	    }
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
232	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
233	        if (currentOwner == null) {
234	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	        }
236	        currentOwner.setAddress(ownerFieldsDto.getAddress());
237	        currentOwner.setCity(ownerFieldsDto.getCity());
238	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
239	        currentOwner.setLastName(ownerFieldsDto.getLastName());
240	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
241	        this.clinicService.saveOwner(currentOwner);
242	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
243	    }
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Transactional
247	    @Override
248	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
249	        Owner owner = this.clinicService.findOwnerById(ownerId);
250	        if (owner == null) {
251	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
252	        }
253	        this.clinicService.deleteOwner(owner);
254	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
255	    }
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
260	        Owner owner = this.clinicService.findOwnerById(ownerId);
261	        if (owner == null) {
262	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
263	        }
264	        HttpHeaders headers = new HttpHeaders();
265	        Pet pet = petMapper.toPet(petFieldsDto);
266	        owner.setId(ownerId);
267	        pet.setOwner(owner);
268	        pet.getType().setName(null);
269	        this.clinicService.savePet(pet);
270	        PetDto petDto = petMapper.toPetDto(pet);
271	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
272	            .buildAndExpand(pet.getId()).toUri());
273	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
274	    }
275	
276	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
277	    @Override
278	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
279	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
280	        if (currentOwner != null) {
281	            Pet currentPet = this.clinicService.findPetById(petId);
282	            if (currentPet != null) {
283	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
284	                currentPet.setName(petFieldsDto.getName());
285	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
286	                this.clinicService.savePet(currentPet);
287	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
288	            }
289	        }
290	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
291	    }
292	
293	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
294	    @Override
295	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
296	        HttpHeaders headers = new HttpHeaders();
297	        Visit visit = visitMapper.toVisit(visitFieldsDto);
298	        Pet pet = new Pet();
299	        pet.setId(petId);
300	        visit.setPet(pet);
301	        this.clinicService.saveVisit(visit);
